insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 27, 'Benjamim, lobo arrebatador; de manhã comerá a presa, e à tarde repartirá os despojos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 28, 'Todos estes foram as doze tribos de Israel: e isto foi o que seu pai lhes disse, e os abençoou; a cada um por sua bênção os abençoou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 29, 'Mandou-lhes logo, e disse-lhes: Eu vou a ser reunido com meu povo: sepultai-me com meus pais na caverna que está no campo de Efrom os heteus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 30, 'Na caverna que está no campo de Macpela, que está diante de Manre na terra de Canaã, a qual comprou Abraão com o mesmo campo de Efrom os heteus, para herança de sepultura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 31, 'Ali sepultaram a Abraão e a Sara sua mulher; ali sepultaram a Isaque e a Rebeca sua mulher; ali também sepultei Lia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 32, 'O campo e a cova que nele está foram comprados dos filhos de Hete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 33, 'E quando acabou Jacó de dar ordens a seus filhos, encolheu seus pés na cama, e expirou; e foi reunido com seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 1, 'Então se lançou José sobre o rosto de seu pai, e chorou sobre ele, e o beijou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 2, 'E mandou José a seus servos médicos que embalsamassem a seu pai; e os médicos embalsamaram a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 3, 'E cumpriam-lhe quarenta dias, porque assim cumpriam os dias dos embalsamados, e choraram-no os egípcios setenta dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 4, 'E passados os dias de seu luto, falou José aos da casa de Faraó, dizendo: Se achei agora favor em vossos olhos, vos rogo que faleis aos ouvidos de Faraó, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 5, 'Meu pai me fez jurar dizendo: Eis que eu morro; em meu sepulcro que eu cavei para mim na terra de Canaã, ali me sepultarás; rogo, pois, que vá eu agora, e sepultarei a meu pai, e voltarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 6, 'E Faraó disse: Vai, e sepulta a teu pai, como ele te fez jurar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 7, 'Então José subiu a sepultar a seu pai; e subiram com ele todos os servos de Faraó, os anciãos de sua casa, e todos os anciãos da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 8, 'E toda a casa de José, e seus irmãos, e a casa de seu pai: somente deixaram na terra de Gósen seus filhos, e suas ovelhas e suas vacas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 9, 'E subiram também com ele carros e cavaleiros, e fez-se um esquadrão muito grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 10, 'E chegaram até a eira de Atade, que está à outra parte do Jordão, e lamentaram ali com grande e muito grave lamentação: e José fez a seu pai luto por sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 11, 'E vendo os moradores da terra, os cananeus, o pranto na eira de Atade, disseram: Pranto grande é este dos egípcios: por isso foi chamado seu nome Abel-Mizraim, que está à outra parte do Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 12, 'Fizeram, pois, seus filhos com ele, segundo lhes havia mandado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 13, 'Pois seus filhos o levaram à terra de Canaã, e o sepultaram na caverna do campo de Macpela, a que havia comprado Abraão com o mesmo campo, para herança de sepultura, de Efrom o heteu, diante de Manre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 14, 'E voltou José ao Egito, ele e seus irmãos, e todos os que subiram com ele a sepultar a seu pai, depois que o sepultou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 15, 'E vendo os irmãos de José que seu pai era morto, disseram: Talvez José nos odeie, e nos retribua de todo o mal que lhe fizemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 16, 'E enviaram a dizer a José: Teu pai mandou antes de sua morte, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 17, 'Assim direis a José: Rogo-te que perdoes agora a maldade de teus irmãos e seu pecado, porque mal te trataram: portanto agora te rogamos que perdoes a maldade dos servos do Deus de teu pai. E José chorou enquanto falavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 18, 'E vieram também seus irmãos, e prostraram-se diante dele, e disseram: Eis-nos aqui por teus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 19, 'E respondeu-lhes José: Não temais: estou eu em lugar de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 20, 'Vós pensastes mal sobre mim, mas Deus o encaminhou para o bem, para fazer o que vemos hoje, para manter em vida muito povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 21, 'Agora, pois, não tenhais medo; eu sustentarei a vós e a vossos filhos. Assim os consolou, e lhes falou ao coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 22, 'E esteve José no Egito, ele e a casa de seu pai; e viveu José cento dez anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 23, 'E viu José os filhos de Efraim até a terceira geração: também os filhos de Maquir, filho de Manassés, foram criados sobre os joelhos de José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 24, 'E José disse a seus irmãos: Eu me morro; mas Deus certamente vos visitará, e vos fará subir desta terra à terra que jurou a Abraão, a Isaque, e a Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 25, 'E fez jurar José aos filhos de Israel, dizendo: Deus certamente vos visitará, e fareis levar daqui meus ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 50, 26, 'E morreu José da idade de cento e dez anos; e embalsamaram-no, e foi posto num caixão no Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 1, 'Estes são os nomes dos filhos de Israel que entraram em Egito com Jacó; cada um entrou com sua família:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 2, 'Rúben, Simeão, Levi e Judá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 3, 'Issacar, Zebulom e Benjamim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 4, 'Dã e Naftali, Gade e Aser.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 5, 'Assim, todas as pessoas que descenderam do corpo de Jacó foram setenta. Porém José estava no Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 6, 'Depois que morreram José, todos os seus irmãos, e toda aquela geração,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 7, 'os filhos de Israel cresceram e multiplicaram, e foram aumentados e fortalecidos grandemente; de maneira que a terra encheu-se deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 8, 'Levantou-se, entretanto, um novo rei sobre o Egito, que não conhecia José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 9, 'Ele disse ao seu povo: Eis que o povo dos filhos de Israel é maior e mais forte que nós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 10, 'Agora, pois, sejamos astutos para com ele, a fim de que não se multiplique, e aconteça que caso venha guerra, ele se alie aos nossos inimigos, lute contra nós, e saia desta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 11, 'Então puseram sobre [o povo de Israel] capatazes para os oprimirem com trabalhos forçados; e edificaram a Faraó as cidades de armazenamento, Pitom e Ramessés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 12, 'Porém, quanto mais os oprimiam, mais se multiplicavam e cresciam. Por isso eles detestavam os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 13, 'Assim os egípcios fizeram os filhos de Israel servirem duramente,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 14, 'e amargaram a vida deles com dura servidão, em fazerem barro e tijolos, em todo trabalho do campo, e em todo o seu serviço, ao qual os obrigavam com rigor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 15, 'E o rei do Egito falou às parteiras das hebreias, uma das quais se chamava Sifrá, e outra Puá, e disse-lhes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 16, 'Quando fizerdes o parto das hebreias, e olhardes os assentos, se for filho, matai-o; e se for filha, então viva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 17, 'Mas as parteiras temeram a Deus, e não fizeram como o rei do Egito lhes mandara; em vez disso, preservaram a vida dos meninos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 18, 'E o rei do Egito mandou chamar às parteiras e lhes perguntou: Por que fizestes isto, que preservastes a vida dos meninos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 19, 'As parteiras responderam a Faraó: As mulheres hebreias não são como as egípcias; pois são fortes, de maneira que dão à luz antes que a parteira chegue a elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 20, 'E Deus fez bem às parteiras. E o povo se multiplicou, e se fortaleceu muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 21, 'E por as parteiras terem temido a Deus, ele constituiu famílias a elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 1, 22, 'Então Faraó deu a todo o seu povo a seguinte ordem: Lançai no rio todo filho que nascer, e a toda filha preservai a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 1, 'Um homem da família de Levi foi, e tomou por mulher uma filha de Levi:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 2, 'A qual concebeu, e deu à luz um filho: e vendo-o que era belo, teve-lhe escondido três meses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 3, 'Porém não podendo ocultar-lhe mais tempo, tomou uma cesta de juncos, e vedou-a com piche e betume, e colocou nela ao menino, e o pôs entre os juncos à beira do rio:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 4, 'E ficou parada uma irmã sua ao longe, para ver o que lhe aconteceria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 5, 'E a filha de Faraó desceu a lavar-se ao rio, e passeando suas virgens pela beira do rio, viu ela a cesta entre os juncos, e enviou uma criada sua a que a tomasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 6, 'E quando a abriu, viu ao menino; e eis que o menino chorava. E tendo compaixão dele, disse: Dos meninos dos hebreus é este.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 7, 'Então sua irmã disse à filha de Faraó: Irei a chamar-te uma ama das hebreias, para que te crie este menino?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 8, 'E a filha de Faraó respondeu: Vai. Então foi a virgem, e chamou à mãe do menino;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 9, 'À qual disse a filha de Faraó: Leva este menino, e cria-o para mim, e eu te o pagarei. E a mulher tomou ao menino, e o criou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 10, 'E quando cresceu o menino, ela o trouxe à filha de Faraó, a qual o adotou, e pôs-lhe por nome Moisés, dizendo: Porque das águas o tirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 11, 'E naqueles dias aconteceu que, crescido já Moisés, saiu a seus irmãos, e viu suas cargas: e observou a um egípcio que feria a um dos hebreus, seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 12, 'E olhou a todas as partes, e vendo que não parecia ninguém, matou ao egípcio, e escondeu-o na areia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 13, 'E saiu ao dia seguinte, e vendo a dois hebreus que brigavam, disse ao que fazia a injúria: Por que feres a teu próximo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 14, 'E ele respondeu: Quem te pôs a ti por príncipe e juiz sobre nós? Pensas matar-me como mataste ao egípcio? Então Moisés teve medo, e disse: Certamente esta coisa é descoberta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 15, 'E ouvindo Faraó este negócio, procurou matar a Moisés: mas Moisés fugiu de diante de Faraó, e habitou na terra de Midiã; e sentou-se junto a um poço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 16, 'Tinha o sacerdote de Midiã sete filhas, as quais vieram a tirar água, para encher os bebedouros e dar de beber as ovelhas de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 17, 'Mas os pastores vieram, e expulsaram-nas: Então Moisés se levantou e defendeu-as, e deu de beber às suas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 18, 'E voltando elas a Reuel seu pai, disse-lhes ele: Por que viestes hoje tão cedo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 19, 'E elas responderam: Um homem egípcio nos defendeu da mão dos pastores, e também tirou a água, e deu de beber as as ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 20, 'E disse a suas filhas: E onde está? Por que deixastes esse homem? Chamai-lhe para que coma pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 21, 'E Moisés concordou em morar com aquele homem; e ele deu a Moisés a sua filha Zípora:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 22, 'A qual lhe deu à luz um filho, e ele lhe pôs por nome Gérson: porque disse: Peregrino sou em terra alheia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 23, 'E aconteceu que depois de muitos dias morreu o rei do Egito, e os filhos de Israel suspiraram por causa da servidão, e clamaram: e subiu a Deus o clamor deles com motivo de sua servidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 24, 'E ouviu Deus o gemido deles, e lembrou-se de seu pacto com Abraão, Isaque e Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 2, 25, 'Deus olhou os filhos de Israel, e Deus os reconheceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 1, 'E apascentando Moisés as ovelhas de Jetro seu sogro, sacerdote de Midiã, levou as ovelhas ao outro lado do deserto, e veio a Horebe, monte de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 2, 'E apareceu-lhe o anjo do SENHOR em uma chama de fogo em meio de uma sarça: e ele olhou, e viu que a sarça ardia em fogo, e a sarça não se consumia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 3, 'Então Moisés disse: Irei eu agora, e verei esta grande visão, por que causa a sarça não se queima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 4, 'E quando o SENHOR viu que ia ver, Deus o chamou do meio da sarça, e disse: Moisés, Moisés! E ele respondeu: Eis-me aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 5, 'E disse: Não te aproximes daqui; tira teus calçados de teus pés, porque o lugar em que estás é terra santa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 6, 'E disse: Eu sou o Deus de teu pai, Deus de Abraão, Deus de Isaque, Deus de Jacó. Então Moisés cobriu seu rosto, porque teve medo de olhar a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 7, 'E disse o SENHOR: Vi a aflição do meu povo que está no Egito, e ouvi seu clamor por causa de seus opressores; pois conheço suas angústias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 8, 'Por isso desci para livrá-los da mão dos egípcios, e tirá-los daquela terra, fazendo-os subir para uma terra boa e larga, para uma terra que flui leite e mel, para o lugar dos cananeus, dos heteus, dos amorreus, dos perizeus, dos heveus e dos jebuseus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 9, 'Eis que o clamor dos filhos de Israel veio a mim, e tenho visto a opressão com que os egípcios os oprimem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 10, 'Vem, pois, agora, e te enviarei a Faraó, para que tires meu povo, os filhos de Israel, do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 11, 'Então Moisés respondeu a Deus: Quem sou eu, para que vá a Faraó, e tire do Egito aos filhos de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 12, 'E ele lhe respondeu: Vai, porque eu serei contigo; e isto te será por sinal de que eu te enviei: logo que houveres tirado este povo do Egito, servireis a Deus sobre este monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 13, 'E disse Moisés a Deus: Eis que, quando eu chegar aos filhos de Israel, e lhes disser, O Deus de vossos pais me enviou a vós; se eles me perguntarem: Qual é seu nome? que lhes responderei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 14, 'Deus respondeu a Moisés: EU SOU O QUE SOU. E disse: Assim dirás aos filhos de Israel: EU SOU me enviou a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 15, 'E disse mais Deus a Moisés: Assim dirás aos filhos de Israel: o SENHOR, o Deus de vossos pais, o Deus de Abraão, Deus de Isaque e Deus de Jacó, me enviou a vós. Este é meu nome para sempre, este é meu memorial por todos os séculos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 16, 'Vai, e junta os anciãos de Israel, e dize-lhes: O SENHOR, o Deus de vossos pais, o Deus de Abraão, de Isaque, e de Jacó, me apareceu, dizendo: Certamente vos visitei, e vi o que se faz convosco no Egito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 17, 'E disse: Eu vos tirarei da aflição do Egito à terra dos cananeus, e dos heteus, e dos amorreus, e dos perizeus, e dos heveus, e dos jebuseus, a uma terra que flui leite e mel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 18, 'E ouvirão tua voz; e irás tu, e os anciãos de Israel, ao rei do Egito, e lhe direis: O SENHOR, o Deus dos hebreus, nos encontrou; portanto nós iremos agora caminho de três dias pelo deserto, para que sacrifiquemos ao SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 19, 'Mas eu sei que o rei do Egito não vos deixará ir a não ser por mão forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 20, 'Porém eu estenderei minha mão, e ferirei ao Egito com todas minhas maravilhas que farei nele, e então vos deixará ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 21, 'E eu darei a este povo favor aos olhos dos egípcios, para que quando vos partirdes, não saiais vazios:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 3, 22, 'Em vez disso pedirá cada mulher à sua vizinha e à sua visitante vasos de prata, vasos de ouro, e roupas; os quais poreis sobre vossos filhos e vossas filhas, e despojareis ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 1, 'Então Moisés respondeu, e disse: Eis que eles não crerão em mim, nem ouvirão minha voz; porque dirão: O SENHOR não apareceu a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 2, 'E o SENHOR disse: Que é isso que tens em tua mão? E ele respondeu: Uma vara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 3, 'E ele lhe disse: Lança-a em terra. E ele a lançou em terra, e tornou-se uma cobra: e Moisés fugia dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 4, 'Então disse o SENHOR a Moisés: Estende tua mão, e toma-a pela cauda. E ele estendeu sua mão, e tomou-a, e tornou-se vara em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 5, 'Por isto crerão que se te apareceu o SENHOR, o Deus de teus pais, o Deus de Abraão, Deus de Isaque, e Deus de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 6, 'E disse-lhe mais o SENHOR: Mete agora tua mão em teu peito. E ele meteu a mão em seu peito; e quando a tirou, eis que sua mão estava leprosa como a neve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 7, 'E disse: Volta a meter tua mão em teu peito; e ele voltou a meter sua mão em seu peito; e voltando-a a tirar do peito, eis que se havia voltado como a outra carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 8, 'Se acontecer, que não te crerem, nem obedecerem à voz do primeiro sinal, crerão à voz do último.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 9, 'E se ainda não crerem nestes dois sinais, nem ouvirem tua voz, tomarás das águas do rio, e as derramará em terra; e se tornarão aquelas águas que tomarás do rio, se tornarão sangue na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 10, 'Então disse Moisés ao SENHOR: Ai Senhor! Eu não sou homem de palavras de ontem nem de anteontem, nem ainda desde que tu falas a teu servo; porque sou lento no fala e incômodo de língua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 11, 'E o SENHOR lhe respondeu: Quem deu a boca ao homem? Ou quem fez ao mudo e ao surdo, ao que vai e ao cego? não sou eu, o SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 12, 'Agora pois, vai, que eu serei em tua boca, e te ensinarei o que tenhas de falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 13, 'E ele disse: Ai Senhor! envia por meio do que hás de enviar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 14, 'Então o SENHOR se irou contra Moisés, e disse: Não conheço eu a teu irmão Arão, levita, e que ele fala bem? E ainda eis que ele sairá para te receber, e vendo-te, se alegrará em seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 15, 'Tu falarás a ele, e porás em sua boca as palavras, e eu serei em tua boca e na sua, e vos ensinarei o que deveis fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 16, 'E ele falará por ti ao povo; e ele te será a ti em lugar de boca, e tu serás para ele em lugar de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 17, 'E tomarás esta vara em tua mão, com a qual farás os sinais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 18, 'Assim se foi Moisés, e voltando a seu sogro Jetro, disse-lhe: Irei agora, e voltarei a meus irmãos que estão em Egito, para ver se ainda vivem. E Jetro disse a Moisés: Vai em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 19, 'Disse também o SENHOR a Moisés em Midiã: Vai, e volta-te ao Egito, porque mataram todos os que procuravam tua morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 20, 'Então Moisés tomou sua mulher e seus filhos, e os pôs sobre um asno, e voltou-se à terra do Egito: tomou também Moisés a vara de Deus em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 21, 'E disse o SENHOR a Moisés: Quando houverdes voltado ao Egito, olha que faças diante de Faraó todas as maravilhas que pus em tua mão: eu, porém, endurecerei seu coração, de modo que não deixará ir ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 22, 'E dirás a Faraó: O SENHOR disse assim: Israel é meu filho, meu primogênito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 23, 'Já te disse que deixes ir a meu filho, para que me sirva, mas não quiseste deixá-lo ir: eis que eu vou a matar a teu filho, o teu primogênito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 24, 'E aconteceu no caminho, que em uma parada o SENHOR lhe saiu ao encontro, e quis matá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 25, 'Então Zípora agarrou uma pedra afiada, e cortou o prepúcio de seu filho, e lançou-o a seus pés, dizendo: Em verdade tu me és um esposo de sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 26, 'Assim lhe deixou logo ir. E ela disse: Esposo de sangue, por causa da circuncisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 27, 'E o SENHOR disse a Arão: Vai receber a Moisés ao deserto. E ele foi, e encontrou-o no monte de Deus, e beijou-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 28, 'Então contou Moisés a Arão todas as palavras do SENHOR que lhe enviava, e todas o sinais que lhe havia dado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 29, 'E foram Moisés e Arão, e juntaram todos os anciãos dos filhos de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 30, 'E falou Arão todas as palavras que o SENHOR havia dito a Moisés, e fez o sinais diante dos olhos do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 4, 31, 'E o povo creu; e ouvindo que o SENHOR havia visitado os filhos de Israel, e que havia visto sua aflição, inclinaram-se e adoraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 1, 'Depois entraram Moisés e Arão a Faraó, e lhe disseram: O SENHOR, o Deus de Israel, disse assim: Deixa ir meu povo a celebrar-me festa no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 2, 'E Faraó respondeu: Quem é o SENHOR, para que eu ouça sua voz e deixe ir a Israel? Não conheço o SENHOR, nem tampouco deixarei Israel ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 3, 'E eles disseram: O Deus dos hebreus nos encontrou: iremos, pois, agora caminho de três dias pelo deserto, e sacrificaremos ao SENHOR nosso Deus; para que não venha sobre nós com pestilência ou com espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 4, 'Então o rei do Egito lhes disse: Moisés e Arão, por que fazeis cessar ao povo de sua obra? Ide a vossas cargas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 5, 'Disse também Faraó: Eis que o povo da terra é agora muito, e vós lhes fazeis cessar de suas cargas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 6, 'E mandou Faraó aquele mesmo dia aos capatazes do povo que o tinham à sua responsabilidade, e a seus governadores, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 7, 'De aqui adiante não dareis palha ao povo para fazer tijolos, como ontem e antes de ontem; vão eles e recolham por si mesmos a palha;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 8, 'E haveis de pôr-lhes a tarefa dos tijolos que faziam antes, e não lhes diminuireis nada; porque estão ociosos, e por isso levantam a voz dizendo: Vamos e sacrificaremos a nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 9, 'Agrave-se a servidão sobre eles, para que se ocupem nela, e não atendam a palavras de mentira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 10, 'E saindo os capatazes do povo e seus governadores, falaram ao povo, dizendo: Assim disse Faraó: Eu não vos dou palha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 11, 'Ide vós, e recolhei palha de onde a achardes; que nada se diminuirá de vossa tarefa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 12, 'Então o povo se espalhou por toda a terra do Egito a colher restolho em lugar de palha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 13, 'E os capatazes os apressavam, dizendo: Acabai vossa obra, a tarefa do dia em seu dia, como quando se vos dava palha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 14, 'E açoitavam aos supervisores dos filhos de Israel, que os capatazes de Faraó haviam posto sobre eles, dizendo: Por que não cumpristes vossa tarefa de tijolos nem ontem nem hoje, como antes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 15, 'E os supervisores dos filhos de Israel vieram a Faraó, e se queixaram a ele, dizendo: Por que o fazes assim com teus servos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 16, 'Não se dá palha a teus servos, e, contudo, nos dizem: Fazei os tijolos. E eis que teus servos são açoitados, e teu povo cai em falta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 17, 'E ele respondeu: Estais ociosos, sim, ociosos, e por isso dizeis: Vamos e sacrifiquemos ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 18, 'Ide, pois, agora, e trabalhai. Não se vos dará palha, e haveis de dar a tarefa dos tijolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 19, 'Então os supervisores dos filhos de Israel se viram em aflição, tendo lhes dito: Não se diminuirá nada de vossos tijolos, da tarefa de cada dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 20, 'E encontrando a Moisés e a Arão, que estavam à vista deles quando saíam de Faraó,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 21, 'Disseram-lhes: Olhe o SENHOR sobre vós, e julgue; pois nos fizestes repulsivos diante de Faraó e de seus servos, dando-lhes a espada nas mãos para que nos matem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 22, 'Então Moisés se voltou ao SENHOR, e disse: Senhor, por que afliges a este povo? para que me enviaste?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 5, 23, 'Porque desde que vim a Faraó para falar-lhe em teu nome, afligiu a este povo; e tu tampouco livraste a teu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 1, 'O SENHOR respondeu a Moisés: Agora verás o que eu farei a Faraó; porque com mão forte os deixará ir; e com mão forte os expulsará de sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 2, 'Falou, todavia, Deus a Moisés, e disse-lhe: Eu sou o SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 3, 'E apareci a Abraão, a Isaque e a Jacó sob o nome de Deus Todo-Poderoso, mas em meu nome, EU-SOU, não me notifiquei a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 4, 'E também estabeleci meu pacto com eles, de dar-lhes a terra de Canaã, a terra em que foram estrangeiros, e na qual peregrinaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 5, 'E também eu ouvi o gemido dos filhos de Israel, aos quais fazem servir os egípcios, e lembrei-me de meu pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 6, 'Portanto dirás aos filhos de Israel: EU SOU O SENHOR; e eu vos tirarei de debaixo das cargas do Egito, e vos livrarei de sua servidão, e vos resgatarei com braço estendido, e com grandes juízos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 7, 'E vos tomarei por meu povo e serei vosso Deus: e vós sabereis que eu sou o SENHOR vosso Deus, que vos tiro de debaixo das cargas do Egito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 8, 'E vos meterei na terra, pela qual levantei minha mão que a daria a Abraão, a Isaque e a Jacó: e eu vos a darei por herança. EU SOU O SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 9, 'Desta maneira falou Moisés aos filhos de Israel: mas eles não escutavam a Moisés por causa da angústia de espírito, e da dura servidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 10, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 11, 'Entra, e fala a Faraó rei do Egito, que deixe ir de sua terra aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 12, 'E respondeu Moisés diante do SENHOR, dizendo: Eis que os filhos de Israel não me escutam: como, pois, me escutará Faraó, ainda mais sendo eu incircunciso de lábios?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 13, 'Então o SENHOR falou a Moisés e a Arão, e deu-lhes mandamento para os filhos de Israel, e para Faraó rei do Egito, para que tirassem aos filhos de Israel da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 14, 'Estes são os chefes das famílias de seus pais. Os filhos de Rúben, o primogênito de Israel: Enoque e Palu, Hezrom e Carmi: estas são as famílias de Rúben.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 15, 'Os filhos de Simeão: Jemuel, e Jamim, e Oade, e Jaquim, e Zoar, e Saul, filho de uma cananeia: estas são as famílias de Simeão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 16, 'E estes são os nomes dos filhos de Levi por suas linhagens: Gérson, e Coate, e Merari: E os anos da vida de Levi foram cento trinta e sete anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 17, 'E os filhos de Gérson: Libni, e Simei, por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 18, 'E os filhos de Coate: Anrão, e Izar, e Hebrom, e Uziel. E os anos da vida de Coate foram cento e trinta e três anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 19, 'E os filhos de Merari: Mali, e Musi: estas são as famílias de Levi por suas linhagens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 20, 'E Anrão tomou por mulher a Joquebede sua tia, a qual lhe deu à luz a Arão e a Moisés. E os anos da vida de Anrão foram cento e trinta e sete anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 21, 'E os filhos de Izar: Corá, e Nefegue e Zicri.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 22, 'E os filhos de Uziel: Misael, e Elzafã e Sitri.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 23, 'E tomou para si Arão por mulher a Eliseba, filha de Aminadabe, irmã de Naassom; a qual lhe deu à luz a Nadabe, e a Abiú, e a Eleazar, e a Itamar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 24, 'E os filhos de Corá: Assir, e Elcana, e Abiasafe: estas são as famílias dos coraítas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 25, 'E Eleazar, filho de Arão, tomou para si mulher das filhas de Putiel, a qual lhe deu à luz a Fineias: E estes são os chefes dos pais dos levitas por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 26, 'Este é aquele Arão e aquele Moisés, aos quais o SENHOR disse: Tirai aos filhos de Israel da terra do Egito por seus esquadrões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 27, 'Estes são os que falaram a Faraó rei do Egito, para tirar do Egito aos filhos de Israel. Moisés e Arão foram estes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 28, 'Quando o SENHOR falou a Moisés na terra do Egito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 29, 'Então o SENHOR falou a Moisés, dizendo: Eu sou o SENHOR; dize a Faraó rei do Egito todas as coisas que eu te digo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 6, 30, 'E Moisés respondeu diante do SENHOR: Eis que sou incircunciso de lábios; como, pois, Faraó me ouvirá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 1, 'O SENHOR disse a Moisés: Olha, eu te constituí como um deus para Faraó, e teu irmão Arão será teu profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 2, 'Tu dirás todas as coisas que eu te mandarei, e Arão teu irmão falará a Faraó, para que deixe os filhos de Israel saírem de sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 3, 'E eu endurecerei o coração de Faraó, e multiplicarei na terra do Egito meus sinais e minhas maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 4, 'E Faraó não vos ouvirá; mas eu porei minha mão sobre o Egito, e tirarei meus exércitos, meu povo, os filhos de Israel, da terra do Egito, com grandes juízos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 5, 'E os egípcios saberão que eu sou o SENHOR, quando eu estender minha mão sobre o Egito, e tirar os filhos de Israel do meio deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 6, 'E fez Moisés e Arão como o SENHOR lhes mandou; fizeram-no assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 7, 'E era Moisés de idade de oitenta anos, e Arão de idade de oitenta e três, quando falaram a Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 8, 'E falou o SENHOR a Moisés e a Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 9, 'Se Faraó vos responder dizendo, Mostrai milagre; dirás a Arão: Toma tua vara, e lança-a diante de Faraó, para que se torne cobra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 10, 'Vieram, pois, Moisés e Arão a Faraó, e fizeram como o SENHOR o havia mandado; e Arão lançou sua vara diante de Faraó e de seus servos, e tornou-se cobra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 11, 'Então Faraó chamou também sábios e encantadores; e os encantadores do Egito com seus encantamentos fizeram também o mesmo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 12, 'Pois lançou cada um sua vara, as quais se tornaram cobras; mas a vara de Arão devorou as varas deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 13, 'E o coração de Faraó se endureceu, e não os escutou; como o SENHOR o havia dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 14, 'Então o SENHOR disse a Moisés: O coração de Faraó está endurecido, que não quer deixar o povo ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 15, 'Vai pela manhã a Faraó, eis que ele estará saindo às águas; e põe-te à beira do rio diante dele, e toma em tua mão a vara que se tornou cobra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 16, 'E dize-lhe: O SENHOR, o Deus dos hebreus, me enviou a ti, dizendo: Deixa meu povo ir, para que me sirvam no deserto; e eis que até agora não quiseste ouvir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 17, 'Assim disse o SENHOR: Nisto conhecerás que eu sou o SENHOR: eis que ferirei com a vara que tenho em minha mão a água que está no rio, e se converterá em sangue:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 18, 'E os peixes que há no rio morrerão, e federá o rio, e os egípcios terão asco de beber a água do rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 19, 'E o SENHOR disse a Moisés: Dize a Arão: Toma tua vara, e estende tua mão sobre as águas do Egito, sobre seus rios, sobre seus ribeiros e sobre seus tanques, e sobre todos os seus depósitos de águas, para que se convertam em sangue, e haja sangue por toda a região do Egito, tanto nos vasos de madeira como nos de pedra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 20, 'E Moisés e Arão fizeram como o SENHOR havia mandado; e levantando a vara feriu as águas que havia no rio, em presença de Faraó e de seus servos; e todas as águas que havia no rio se converteram em sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 21, 'Assim os peixes que havia no rio morreram; e o rio se contaminou, que os egípcios não podiam beber dele; e houve sangue por toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 22, 'E os encantadores do Egito fizeram o mesmo com seus encantamentos: e o coração de Faraó se endureceu, e não os escutou; como o SENHOR o havia dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 23, 'E Faraó, tornando, voltou-se a sua casa, e não pôs seu coração ainda nisto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 24, 'E por todo o Egito fizeram poços ao redor do rio para beber, porque não podiam beber das águas do rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 7, 25, 'E cumpriram-se sete dias depois que o SENHOR feriu o rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 1, 'Então o SENHOR disse a Moisés: Entra à presença de Faraó, e dize-lhe: O SENHOR disse assim: Deixa meu povo ir, para que me sirvam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 2, 'E se não o quiseres deixar ir, eis que ferirei com rãs todo os teu território;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 3, 'E o rio criará rãs, que subirão, e entrarão em tua casa, e no teu quarto, e sobre tua cama, e nas casas de teus servos, e em teu povo, e em teus fornos, e em tuas amassadeiras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 4, 'E as rãs subirão sobre ti, e sobre teu povo, e sobre todos os teus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 5, 'E o SENHOR disse a Moisés: Dize a Arão: Estende tua mão com tua vara sobre os rios, ribeiros, e tanques, para que faça vir rãs sobre a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 6, 'Então Arão estendeu sua mão sobre as águas do Egito, e subiram rãs que cobriram a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 7, 'E os encantadores fizeram o mesmo com seus encantamentos, e fizeram vir rãs sobre a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 8, 'Então Faraó chamou Moisés e Arão, e disse-lhes: Orai ao SENHOR que tire as rãs de mim e de meu povo; e deixarei ir ao povo, para que sacrifique ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 9, 'E disse Moisés a Faraó: Tem a honra em meu lugar [de dizer] quando orarei por ti, e por teus servos, e por teu povo, para que as rãs sejam tiradas de ti, e de tuas casas, e que somente se restem no rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 10, 'E ele disse: Amanhã. E Moisés respondeu: Será feito conforme tua palavra, para que conheças que não há ninguém como o SENHOR nosso Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 11, 'E as rãs se irão de ti, e de tuas casas, e de teus servos, e de teu povo, e somente se ficarão no rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 12, 'Então saíram Moisés e Arão da presença de Faraó, e clamou Moisés ao SENHOR acerca das rãs que havia posto a Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 13, 'E o SENHOR fez conforme a palavra de Moisés, e morreram as rãs das casas, dos pátios, e dos campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 14, 'E as juntaram em amontoados, e faziam cheirar mal a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 15, 'E vendo Faraó que lhe haviam dado repouso, agravou seu coração, e não os escutou; como o SENHOR o havia dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 16, 'Então o SENHOR disse a Moisés: Dize a Arão: Estende a tua vara, e fere o pó da terra, para que se voltem piolhos por toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 17, 'E eles o fizeram assim; e Arão estendeu sua mão com sua vara, e feriu o pó da terra, o qual se tornou piolhos, tanto nos homens como nos animais; todo o pó da terra se tornou piolhos em toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 18, 'E os encantadores tentaram fizeram assim também, para tirar piolhos com seus encantamentos; mas não puderam. E havia piolhos tanto nos homens como nos animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 19, 'Então os magos disseram a Faraó: Dedo de Deus é este. Mas o coração de Faraó se endureceu, e não os escutou; como o SENHOR o havia dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 20, 'E o SENHOR disse a Moisés: Levanta-te de manhã e põe-te diante de Faraó, eis que ele estará saindo às águas; e dize-lhe: o SENHOR disse assim: Deixa meu povo ir, para que me sirva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 21, 'Porque se não deixares meu povo ir, eis que enviarei sobre ti, e sobre teus servos, e sobre teu povo, e sobre tuas casas toda variedade de moscas; e as casas dos egípcios se encherão de toda variedade de moscas, e também a terra onde eles estiverem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 22, 'E naquele dia separarei a terra de Gósen, na qual meu povo habita, para que nenhuma variedade de moscas haja nela; a fim de que saibas que eu sou o SENHOR no meio da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 23, 'E eu porei remissão entre meu povo e o teu. Amanhã será este sinal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 24, 'E o SENHOR o fez assim: veio toda variedade de moscas incômodas sobre a casa de Faraó, e sobre as casas de seus servos, e sobre toda a terra do Egito; e a terra foi contaminada por causa delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 25, 'Então Faraó chamou a Moisés e a Arão, e disse-lhes: Andai, sacrificai a vosso Deus nesta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 26, 'E Moisés respondeu: Não convém que façamos assim, porque sacrificaríamos ao SENHOR nosso Deus a abominação dos egípcios. Eis que, se sacrificássemos a abominação dos egípcios diante deles, não nos apedrejariam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 27, 'Caminho de três dias iremos pelo deserto, e sacrificaremos ao SENHOR nosso Deus, como ele nos dirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 28, 'E disse Faraó: Eu vos deixarei ir para que sacrifiqueis ao SENHOR vosso Deus no deserto, contanto que não vades mais longe; orai por mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 29, 'E respondeu Moisés: Eis que, quando eu sair de tua presença, rogarei ao SENHOR que as diversas variedades de moscas se afastem de Faraó, e de seus servos, e de seu povo amanhã; contanto que Faraó não falte mais, não deixando o povo ir sacrificar ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 30, 'Então Moisés saiu da presença de Faraó, e orou ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 31, 'E o SENHOR fez conforme a palavra de Moisés; e tirou todas aquelas moscas de Faraó, e de seus servos, e de seu povo, sem que restasse uma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 8, 32, 'Mas Faraó agravou ainda esta vez seu coração, e não deixou o povo ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 1, 'Então o SENHOR disse a Moisés: Entra a Faraó, e dize-lhe: o SENHOR, o Deus dos hebreus, diz assim: Deixa ir a meu povo, para que me sirvam;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 2, 'Porque se não o queres deixar ir, e os detiverdes ainda,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 3, 'Eis que a mão do SENHOR será sobre teus gados que estão no campo, cavalos, asnos, camelos, vacas e ovelhas, com pestilência gravíssima:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 4, 'E o SENHOR fará separação entre os gados de Israel e os do Egito, de modo que nada morra de todo o dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 5, 'E o SENHOR assinalou tempo, dizendo: Amanhã fará o SENHOR esta coisa na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 6, 'E o dia seguinte o SENHOR fez aquilo, e morreu todo o gado do Egito; mas do gado dos filhos de Israel não morreu um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 7, 'Então Faraó enviou, e eis que do gado dos filhos de Israel não havia um morto sequer. Mas o coração de Faraó se agravou, e não deixou ir ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 8, 'E o SENHOR disse a Moisés e a Arão: Tomai punhados de cinza de um forno, e espalha-a Moisés até o céu diante de Faraó:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 9, 'E virá a ser pó sobre toda a terra do Egito, o qual originará sarna que cause feridas com ulcerações nos homens e nos animais, por toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 10, 'E tomaram a cinza do forno, e puseram-se diante de Faraó, e espalhou-a Moisés até o céu; e veio uma sarna que causava feridas com ulcerações tanto nos homens como nos animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 11, 'E os magos não podiam estar diante de Moisés por causa das feridas, porque houve sarna nos magos e em todos os egípcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 12, 'E o SENHOR endureceu o coração de Faraó, e não os ouviu; como o SENHOR o disse a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 13, 'Então o SENHOR disse a Moisés: Levanta-te de manhã, e põe-te diante de Faraó, e dize-lhe: o SENHOR, o Deus dos hebreus, disse assim: Deixa ir a meu povo, para que me sirva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 14, 'Porque eu enviarei esta vez todas minhas pragas a teu coração, sobre teus servos, e sobre teu povo, para que entendas que não há outro como eu em toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 15, 'Porque agora eu estenderei minha mão para ferir a ti e a teu povo de pestilência, e serás tirado da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 16, 'E à verdade eu te pus para declarar em ti meu poder, e que meu Nome seja contado em toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 17, 'Todavia te exaltas tu contra meu povo, para não deixá-los ir?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 18, 'Eis que amanhã a estas horas eu farei chover granizo muito grave, qual nunca foi em Egito, desde o dia que se fundou até agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 19, 'Envia, pois, a recolher teu gado, e tudo o que tens no campo; porque todo homem ou animal que se achar no campo, e não for recolhido a casa, o granizo descerá sobre ele, e morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 20, 'Dos servos de Faraó o que temeu a palavra do SENHOR, fez fugir seus criados e seu gado a casa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 21, 'Mas o que não pôs em seu coração a palavra do SENHOR, deixou seus criados e seus gados no campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 22, 'E o SENHOR disse a Moisés: Estende a tua mão até o céu, para que venha granizo em toda a terra do Egito sobre os homens, e sobre os animais, e sobre toda a erva do campo na terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 23, 'E Moisés estendeu sua vara até o céu, e o SENHOR fez trovejar e cair granizo, e o fogo corria pela terra; e choveu o SENHOR granizo sobre a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 24, 'Houve, pois, granizo, e fogo misturado com o granizo, tão grande, qual nunca houve em toda a terra do Egito desde que foi habitada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 25, 'E aquele granizo feriu em toda a terra do Egito todo o que estava no campo, tanto homens como animais; o granizo também feriu toda erva do campo, e quebrou os galhos de todas as árvores daquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 26, 'Somente na terra de Gósen, onde os filhos de Israel estavam, não houve granizo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 27, 'Então Faraó mandou chamar a Moisés e a Arão, e lhes disse: Pequei esta vez: o SENHOR é justo, e eu e meu povo ímpios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 28, 'Orai ao SENHOR: e cessem os trovões de Deus e o granizo; e eu vos deixarei ir, e não vos detereis mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 29, 'E respondeu-lhe Moisés: Em saindo eu da cidade estenderei minhas mãos ao SENHOR, e os trovões cessarão, e não haverá mais granizo; para que saibas que do SENHOR é a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 30, 'Mas eu sei que nem tu nem teus servos temereis todavia a presença do Deus o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 31, 'O linho, pois, e a cevada foram feridos; porque a cevada estava já espigada, e o linho em flor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 32, 'Mas o trigo e o centeio não foram feridos; porque eram tardios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 33, 'E saído Moisés da presença de Faraó da cidade, estendeu suas mãos ao SENHOR, e cessaram os trovões e o granizo; e a chuva não caiu mais sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 34, 'E vendo Faraó que a chuva havia cessado e o granizo e os trovões, perseverou em pecar, e agravou seu coração, ele e seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 9, 35, 'E o coração de Faraó se endureceu, e não deixou ir aos filhos de Israel; como o SENHOR o havia dito por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 1, 'E o SENHOR disse a Moisés: Vai à presença de Faraó; porque agravei o coração dele, e o coração de seus servos, para fazer entre eles estes meus sinais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 2, 'e para que contes a teus filhos e a teus netos as coisas que eu fiz em Egito, e meus sinais que realizei entre eles; e para que saibais que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 3, 'Então vieram Moisés e Arão a Faraó, e lhe disseram: O SENHOR, o Deus dos hebreus disse assim: Até quando não quererás te humilhar diante de mim? Deixa ir a meu povo para que me sirvam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 4, 'E se ainda recusas deixá-lo ir, eis que trarei amanhã gafanhotos em teu território,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 5, 'os quais cobrirão a face da terra, de modo que não se possa ver a terra; e ela comerá o que restou salvo, o que vos restou do granizo; comerão também toda árvore que vos produz fruto no campo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 6, 'e encherão tuas casas, e as casas de todos os teus servos, e as casas de todos os egípcios, que nunca viram teus pais nem teus avós, desde que eles existiram sobre a terra até hoje. E voltou-se, e saiu da presença de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 7, 'Então os servos de Faraó lhe disseram: Até quando este nos será por laço? Deixa ir a estes homens, para que sirvam ao SENHOR seu Deus; ainda não sabes que Egito está destruído?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 8, 'E Moisés e Arão voltaram a ser chamados a Faraó, o qual lhes disse: Andai, servi ao SENHOR vosso Deus. Quem e quem são os que irão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 9, 'E Moisés respondeu: Iremos com nossos meninos e com nossos idosos, com nossos filhos e com nossas filhas; iremos com nossas ovelhas e com nossas vacas, porque temos solenidade do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 10, 'E ele lhes disse: Assim esteja o SENHOR convosco se eu vos deixar ir a vós e a vossos meninos; olhai como o mal está diante de vosso rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 11, 'Não será assim: ide agora vós, os homens, e servi ao SENHOR; pois isto é o que vós pedistes. E eles foram expulsos de diante de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 12, 'Então o SENHOR disse a Moisés: Estende tua mão sobre a terra do Egito para gafanhotos, a fim de que subam sobre a terra do Egito, e consumam tudo o que o granizo deixou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 13, 'E estendeu Moisés sua vara sobre a terra do Egito, e o SENHOR trouxe um vento oriental sobre aquela terra durante todo aquele dia e toda aquela noite; e na manhã o vento oriental trouxe os gafanhotos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 14, 'E os gafanhotos subiram sobre toda a terra do Egito, e pousaram em todos os termos do Egito, em gravíssima maneira; antes dela não houve gafanhotos semelhantes, nem depois deles vieram outros tais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 15, 'E cobriram a face de todo o país, e aquela terra se escureceu; e consumiram toda a erva da terra, e todo o fruto das árvores que o granizo havia deixado; que não restou coisa verde em árvores nem em erva do campo, por toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 16, 'Então Faraó fez chamar depressa a Moisés e a Arão, e disse: Pequei contra o SENHOR vosso Deus, e contra vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 17, 'Mas rogo agora que perdoes meu pecado somente esta vez, e que oreis ao SENHOR vosso Deus que tire de mim somente esta morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 18, 'E saiu da presença de Faraó, e orou ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 19, 'E o SENHOR voltou um vento ocidental fortíssimo, e tirou os gafanhotos, e lançou-os ao mar Vermelho; nem um gafanhoto restou ao todo o território do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 20, 'Mas o SENHOR endureceu o coração de Faraó; e não permitiu a saída dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 21, 'E o SENHOR disse a Moisés: Estende tua mão até o céu, para que haja trevas sobre a terra do Egito, tão intensas que qualquer um as apalpe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 22, 'E estendeu Moisés sua mão até o céu, e houve densas durante trevas três dias por toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 23, 'Nenhum podia ver seu próximo, nem ninguém se levantou de seu lugar em três dias; mas todos os filhos de Israel tinham luz em suas habitações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 24, 'Então Faraó fez chamar a Moisés, e disse: Ide, servi ao SENHOR; somente restem vossas ovelhas e vossas vacas; vão também vossas crianças convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 25, 'E Moisés respondeu: Tu também nos entregarás sacrifícios e holocaustos para que sacrifiquemos ao SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 26, 'Nossos gados irão também conosco; não ficará nem uma casco; porque deles tomaremos para servir ao SENHOR nosso Deus; e não sabemos com que serviremos ao SENHOR, até que cheguemos ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 27, 'Mas o SENHOR endureceu o coração de Faraó, e não quis deixá-los ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 28, 'E disse-lhe Faraó: Retira-te de mim; guarda-te que não vejas mais meu rosto, porque em qualquer dia que vires meu rosto, morrerás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 10, 29, 'E Moisés respondeu: Bem disseste; não verei mais teu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 11, 1, 'E o SENHOR disse a Moisés: Uma praga trarei ainda sobre Faraó, e sobre o Egito; depois da qual ele vos deixará ir daqui; e seguramente vos expulsará daqui de todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 11, 2, 'Fala agora ao povo, e que cada um peça a seu vizinho, e cada uma à sua vizinha, objetos de prata e de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 11, 3, 'E o SENHOR fez o povo ser favorecido aos olhos dos egípcios. Também Moisés era muito grande homem na terra do Egito, aos olhos dos servos de Faraó, e aos olhos do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 11, 4, 'E disse Moisés: o SENHOR disse assim: À meia noite eu sairei por meio do Egito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 11, 5, 'E morrerá todo primogênito na terra do Egito, desde o primogênito de Faraó que se assenta em seu trono, até o primogênito da serva que está atrás do moinho; e todo primogênito dos animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 11, 6, 'E haverá grande clamor por toda a terra do Egito, qual nunca foi, nem jamais será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 11, 7, 'Mas entre todos os filhos de Israel, desde o homem até o animal, nem um cão moverá sua língua; para que saibais que o SENHOR fará diferença entre os egípcios e os israelitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 11, 8, 'E descerão a mim todos estes teus servos, e inclinados diante de mim dirão: Sai tu, e todo o povo que está abaixo de ti; e depois disto eu sairei. E saiu-se muito irado da presença de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 11, 9, 'E o SENHOR disse a Moisés: Faraó não vos ouvirá, para que minhas maravilhas se multipliquem na terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 11, 10, 'E Moisés e Arão fizeram todos estes prodígios diante de Faraó; mas o SENHOR havia endurecido o coração de Faraó, e não permitiu que os filhos de Israel saíssem da sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 1, 'E falou o SENHOR a Moisés e a Arão na terra do Egito, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 2, 'Este mês vos será o princípio dos meses; será este para vós o primeiro nos meses do ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 3, 'Falai a toda a congregação de Israel, dizendo: No [dia] dez deste mês tome para si cada um um cordeiro pelas famílias dos pais, um cordeiro por família:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 4, 'Mas se a família for pequena que não seja capaz de comer o cordeiro inteiro, então tomará a seu vizinho imediato à sua casa, e segundo o número das pessoas, cada um conforme seu comer, fareis a conta sobre o cordeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 5, 'O cordeiro será sem defeito, macho de um ano; vós o tomareis das ovelhas ou das cabras:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 6, 'E o guardareis até o dia catorze desse mês; e toda a congregação do povo de Israel o imolará ao entardecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 7, 'E tomarão do sangue, e o porão nos dois postes e na verga das casas em que o comerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 8, 'E naquela noite comerão a carne assada ao fogo, e pães sem levedura; com ervas amargas o comerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 9, 'Nenhuma coisa comereis dele crua, nem cozida em água, mas sim assada ao fogo; sua cabeça com seus pés e seus intestinos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 10, 'Nenhuma coisa deixareis dele até a manhã; e o que houver restado até a manhã, queimareis no fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 11, 'E assim tereis de comê-lo: cingidos vossos lombos, vossos calçados em vossos pés, e vosso bordão em vossa mão; e o comereis apressadamente: é a Páscoa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 12, 'Pois eu passarei naquela noite pela terra do Egito, e ferirei todo primogênito na terra do Egito, tanto nos homens como nos animais; e executarei juízos em todos os deuses do Egito. EU SOU O SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 13, 'E o sangue vos será por sinal nas casas onde vós estejais; e verei o sangue, e passarei de vós, e não haverá em vós praga de mortandade, quando ferirei a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 14, 'E hoje vos será em memória, e tereis de celebrá-lo como solenidade ao SENHOR durante vossas gerações; por estatuto perpétuo o celebrareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 15, 'Sete dias comereis pães sem levedura; e assim o primeiro dia fareis que não haja levedura em vossas casas; porque qualquer um que comer levedado desde o primeiro dia até o sétimo, aquela alma será eliminada de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 16, 'No primeiro dia haverá santa convocação, e também no sétimo dia tereis uma santa convocação; nenhuma obra se fará neles, exceto somente que prepareis o que cada qual houver de comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 17, 'E guardareis a festa dos pães ázimos, porque em este mesmo dia tirei vossos exércitos da terra do Egito: portanto guardareis hoje em vossas gerações por costume perpétuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 18, 'No mês primeiro, o dia catorze do mês pela tarde, comereis os pães sem levedura, até o vinte e um do mês pela tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 19, 'Por sete dias não se achará levedura em vossas casas, porque qualquer um que comer algo levedado, tanto o estrangeiro como o natural da terra, tal alma será eliminada da congregação de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 20, 'Nenhuma coisa levedada comereis; em todas as vossas habitações comereis pães sem levedura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 21, 'E Moisés convocou a todos os anciãos de Israel, e disse-lhes: Tirai, e tomai para vós cordeiros por vossas famílias, e sacrificai a páscoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 22, 'E tomai um molho de hissopo, e molhai-lhe no sangue que estará em uma bacia, e untai a verga e os dois postes com o sangue que estará na bacia; e nenhum de vós saia das portas de sua casa até a manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 23, 'Porque o SENHOR passará ferindo os egípcios; e quando vir o sangue na verga e nos dois postes, passará o SENHOR aquela porta, e não deixará entrar o feridor em vossas casas para ferir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 24, 'E guardareis isto por estatuto para vós e para vossos filhos para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 25, 'E será que quando houverdes entrado na terra que o SENHOR vos dará, como tem falado, que guardareis este rito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 26, 'E quando vos perguntarem vossos filhos: Que rito é este vosso?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 27, 'Respondereis: É o sacrifício da Páscoa do SENHOR, que passou nas casas dos filhos de Israel no Egito, quando feriu os egípcios, e livrou nossas casas. Então o povo se inclinou e adorou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 28, 'E os filhos de Israel se foram, e fizeram exatamente assim, como o SENHOR havia mandado a Moisés e a Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 29, 'E aconteceu que à meia-noite o SENHOR feriu todo primogênito na terra do Egito, desde o primogênito de Faraó que se sentava sobre seu trono, até o primogênito do prisioneiro que estava no cárcere, e todo primogênito dos animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 30, 'E levantou-se naquela noite Faraó, ele e todos os seus servos, e todos os egípcios; e havia um grande clamor no Egito, porque não havia casa onde não houvesse morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 31, 'E fez chamar a Moisés e a Arão de noite, e disse-lhes: Saí do meio de meu povo vós, e os filhos de Israel; e ide, servi ao SENHOR, como dissestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 32, 'Tomai também vossas ovelhas e vossas vacas, como dissestes, e ide; e abençoai também a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 33, 'E os egípcios apressavam ao povo, dando pressa a expulsá-los da terra; porque diziam: Todos seremos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 34, 'E levou o povo sua massa antes que se levedasse, suas massas envoltas em suas mantas sobre seus ombros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 35, 'E fizeram os filhos de Israel conforme o mandamento de Moisés, pedindo aos egípcios objetos de prata, e objetos de ouro, e roupas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 36, 'E o SENHOR deu favor ao povo diante dos egípcios, e deram-lhes; e eles despojaram os egípcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 37, 'E partiram os filhos de Israel de Ramessés a Sucote, como seiscentos mil homens a pé, sem contar os meninos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 38, 'E também subiu com eles grande multidão de diversa variedade de gentes; e ovelhas, e gados muito muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 39, 'E cozeram tortas sem levedura da massa que haviam tirado do Egito; porque não havia levedado, porquanto expulsando-os os egípcios, não haviam podido deter-se, nem ainda preparar para si comida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 40, 'O tempo que os filhos de Israel habitaram no Egito foi quatrocentos e trinta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 41, 'E passados quatrocentos e trinta anos, no mesmo dia saíram todos os exércitos do SENHOR da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 42, 'É noite de guardar ao SENHOR, por havê-los tirado nela da terra do Egito. Esta noite devem guardar ao SENHOR todos os filhos de Israel em suas gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 43, 'E o SENHOR disse a Moisés e a Arão: Esta é a ordenança da Páscoa: Nenhum estrangeiro comerá dela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 44, 'Mas todo servo humano comprado por dinheiro, comerá dela depois que o houveres circuncidado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 45, 'O estrangeiro e o assalariado não comerão dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 46, 'Em uma casa se comerá, e não levarás daquela carne fora de casa, nem quebrareis osso seu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 47, 'Toda a congregação de Israel o sacrificará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 48, 'Mas se algum estrangeiro peregrinar contigo, e quiser fazer a páscoa ao SENHOR, seja-lhe circuncidado todo homem, e então se chegará a fazê-la, e será como o natural da terra; mas nenhum incircunciso comerá dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 49, 'A mesma lei será para o natural e para o estrangeiro que peregrinar entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 50, 'Assim o fizeram todos os filhos de Israel; como mandou o SENHOR a Moisés e a Arão, assim o fizeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 12, 51, 'E naquele mesmo dia o SENHOR tirou os filhos de Israel da terra do Egito, agrupados em seus esquadrões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 1, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 2, 'Santifica para mim todo primogênito, qualquer um que abre madre entre os filhos de Israel, tanto dos homens como dos animais: meu é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 3, 'E Moisés disse ao povo: Tende memória deste dia, no qual saístes do Egito, da casa de servidão; pois o SENHOR vos tirou daqui com mão forte; portanto, não comereis levedado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 4, 'Vós saís hoje no mês de Abibe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 5, 'E quando o SENHOR te houver posto na terra dos cananeus, e dos heteus, e dos amorreus, e dos heveus, e dos jebuseus, a qual jurou a teus pais que te daria, terra que destila leite e mel, farás este serviço em este mês.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 6, 'Sete dias comerás sem levedar, e o sétimo dia será festa ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 7, 'Por os sete dias se comerão os pães sem levedura; e não se verá contigo levedado, nem levedura ao todo teu termo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 8, 'E contarás naquele dia a teu filho, dizendo: Isto se faz por causa do que o SENHOR fez comigo quando me tirou do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 9, 'E será para ti como um sinal sobre tua mão, e como uma memória diante de teus olhos, para que a lei do SENHOR esteja na tua boca; pois com mão forte te tirou o SENHOR do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 10, 'Portanto, tu guardarás este rito em seu tempo de ano em ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 11, 'E quando o SENHOR te houver posto na terra dos cananeus, como jurou a ti e a teus pais, e quando te a houver dado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 12, 'Farás passar ao SENHOR todo o que abrir a madre, também todo primeiro que abrir a madre de teus animais: os machos serão do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 13, 'Mas todo primogênito de asno resgatarás com um cordeiro; e se não o resgatares, o degolarás: também resgatarás todo homem primogênito de teus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 14, 'E quando amanhã te perguntar teu filho, dizendo: Que é isto? Tu lhe dirás: o SENHOR tirou com mão forte do Egito, de casa de servidão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 15, 'E endurecendo-se Faraó em não nos deixar ir, o SENHOR matou na terra do Egito a todo primogênito, desde o primogênito homem até o primogênito do animal; e por esta causa eu sacrifico ao SENHOR todo primogênito macho, e resgato todo primogênito de meus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 16, 'Será para ti, pois, como um sinal sobre tua mão, e por uma memória diante de teus olhos; já que o SENHOR tirou do Egito com mão forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 17, 'E logo que Faraó deixou ir ao povo, Deus não os levou pelo caminho da terra dos filisteus, que estava próxima; porque disse Deus: Que talvez não se arrependa o povo quando virem a guerra, e se voltem ao Egito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 18, 'Mas fez Deus ao povo que rodeasse pelo caminho do deserto do mar Vermelho. E subiram os filhos de Israel do Egito armados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 19, 'Tomou também consigo Moisés os ossos de José, o qual havia juramentado aos filhos de Israel, dizendo: Deus certamente vos visitará, e fareis subir meus ossos daqui convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 20, 'E partidos de Sucote, assentaram acampamento em Etã, à entrada do deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 21, 'E o SENHOR ia diante deles de dia em uma coluna de nuvem, para guiá-los pelo caminho; e de noite em uma coluna de fogo para iluminá-los, a fim de que andassem de dia e de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 13, 22, 'Nunca se partiu de diante do povo a coluna de nuvem de dia, nem de noite a coluna de fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 2, 'Fala aos filhos de Israel que deem a volta, e assentem seu acampamento diante de Pi-Hairote, entre Migdol e o mar até Baal-Zefom: diante dele assentareis o campo, junto ao mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 3, 'Porque Faraó dirá dos filhos de Israel: Estão andando confusos na terra, o deserto os encurralou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 4, 'E eu endurecerei o coração de Faraó para que os siga; e serei glorificado em Faraó e em todo o seu exército; e saberão os egípcios que eu sou o SENHOR. E eles o fizeram assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 5, 'E foi dado aviso ao rei do Egito como o povo se fugia: e o coração de Faraó e de seus servos se voltou contra o povo, e disseram: Como fizemos isto de haver deixado ir a Israel, para que não nos sirva?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 6, 'E preparou seu carro, e tomou consigo seu povo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 7, 'e tomou seiscentos carros escolhidos, e todos os carros do Egito, e os capitães sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 8, 'E endureceu o SENHOR o coração de Faraó rei do Egito, e seguiu aos filhos de Israel; mas os filhos de Israel haviam saído com mão poderosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 9, 'Seguindo-os, pois, os egípcios, com toda a cavalaria e carros de Faraó, seus cavaleiros, e todo seu exército, alcançaram-nos assentando o acampamento junto ao mar, ao lado de Pi-Hairote, diante de Baal-Zefom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 10, 'E quando Faraó se aproximou, os filhos de Israel levantaram seus olhos, e eis que os egípcios vinham atrás deles; por isso temeram muito, e os filhos de Israel clamaram ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 11, 'E disseram a Moisés: Não havia sepulcros no Egito, que nos tiraste para morrermos no deserto? Por que o fizeste assim conosco, que nos tiraste do Egito?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 12, 'Não é isto o que te falamos no Egito, dizendo: Deixa-nos servir aos egípcios? Pois melhor nos teria sido servir aos egípcios, que morrermos no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 13, 'E Moisés disse ao povo: Não temais; ficai quietos, e vede a salvação do SENHOR, que ele fará hoje convosco; porque os egípcios que hoje vistes, nunca mais para sempre os vereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 14, 'O SENHOR lutará por vós, e vós ficai quietos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 15, 'Então o SENHOR disse a Moisés: “Por que clamas a mim? Diz aos filhos de Israel que marchem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 16, 'Quanto a ti, ergue a tua vara, estende a tua mão sobre o mar, e divide-o. Que os filhos de Israel entre por meio do mar em seco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 17, 'E eu, eis que endurecerei o coração dos egípcios, para que os sigam. E eu me glorificarei em Faraó, e em todo o seu exército, e em suas carruagens, e em sua cavalaria;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 18, 'E os egípcios saberão que eu sou o SENHOR, quando eu me glorificar em Faraó, em seus carros, e em seus cavaleiros.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 19, 'E o anjo de Deus que ia diante do acampamento de Israel, se separou, e ia detrás deles; e também a coluna de nuvem que ia diante deles, separou-se, e pôs-se atrás deles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 20, 'e ia entre o acampamento dos egípcios e o acampamento de Israel; e era nuvem e trevas para aqueles, e iluminava a Israel de noite; e em toda aquela noite não se aproximaram uns dos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 21, 'E estendeu Moisés sua mão sobre o mar, e fez o SENHOR que o mar se retirasse por forte vento oriental toda aquela noite; e tornou o mar em seco, e as águas restaram divididas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 22, 'Então os filhos de Israel entraram por meio do mar em seco, tendo as águas como muro à sua direita e à sua esquerda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 23, 'E seguindo-os os egípcios, entraram atrás deles até o meio do mar, toda a cavalaria de Faraó, seus carros, e seus cavaleiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 24, 'E aconteceu à vigília da manhã, que o SENHOR olhou ao campo dos egípcios desde a coluna de fogo e nuvem, e perturbou o acampamento dos egípcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 25, 'E tirou-lhes as rodas de seus carros, e transtornou-os gravemente. Então os egípcios disseram: Fujamos de diante de Israel, porque o SENHOR luta por eles contra os egípcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 26, 'E o SENHOR disse a Moisés: Estende tua mão sobre o mar, para que as águas voltem sobre os egípcios, sobre seus carros, e sobre sua cavalaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 27, 'E Moisés estendeu sua mão sobre o mar, e o mar se voltou em sua força quando amanhecia; e os egípcios iam até ela: e o SENHOR derrubou aos egípcios em meio do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 28, 'E voltaram as águas, e cobriram os carros e a cavalaria, e todo o exército de Faraó que havia entrado atrás eles no mar; não restou deles nenhum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 29, 'E os filhos de Israel foram por meio do mar em seco, tendo as águas por muro à sua direita e à sua esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 30, 'Assim salvou o SENHOR aquele dia a Israel da mão dos egípcios; e Israel viu aos egípcios mortos à beira do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 14, 31, 'E viu Israel aquele grande feito que o SENHOR executou contra os egípcios: e o povo temeu ao SENHOR, e creram no SENHOR e em Moisés seu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 1, 'Então cantou Moisés e os filhos de Israel este cântico ao SENHOR, e disseram: Cantarei eu ao SENHOR, porque se triunfou grandemente, Lançando no mar ao cavalo e ao que nele subia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 2, 'O SENHOR é minha força, e minha canção, E foi-me por salvação: Este é meu Deus, e a este engrandecerei; Deus de meu pai, e a este exaltarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 3, 'O SENHOR, homem de guerra; o SENHOR é seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 4, 'Os carros de Faraó e a seu exército lançou no mar; E seus escolhidos príncipes foram afundados no mar Vermelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 5, 'Os abismos os cobriram; Como pedra desceram aos profundos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 6, 'Tua mão direita, ó SENHOR, foi engrandecida em força; Tua mão direita, ó SENHOR, quebrantou ao inimigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 7, 'E com a grandeza de tua poder transtornaste aos que se levantaram contra ti: Enviaste teu furor; os tragou como o restolho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 8, 'Com o sopro de tuas narinas se amontoaram as águas; Pararam-se as correntezas como em um amontoado; Os abismos se solidificaram em meio do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 9, 'O inimigo disse: Perseguirei, prenderei, repartirei despojos; Minha alma se encherá deles; Tirarei minha espada, minha mão os destruirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 10, 'Sopraste com teu vento, cobriu-os o mar: Afundaram-se como chumbo nas impetuosas águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 11, 'Quem como tu, SENHOR, entre os deuses? Quem como tu, magnífico em santidade, Terrível em louvores, autor de maravilhas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 12, 'Estendeste a tua mão direita; a terra os tragou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 13, 'Conduziste em tua misericórdia a este povo, ao qual salvaste; Levaste-o com tua força à habitação de teu santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 14, 'Ouviram-no os povos, e tremerão; Dor se apoderará dos moradores da filístia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 15, 'Então os príncipes de Edom se perturbarão; Aos robustos de Moabe os ocupará tremor; Todos os moradores de Canaã se abaterão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 16, 'Caia sobre eles tremor e espanto; À grandeza de teu braço emudeçam como uma pedra; Até que tenha passado teu povo, ó SENHOR, Até que tenha passado este povo que tu resgataste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 17, 'Tu os introduzirás e os plantarás no monte de tua herança, No lugar de tua morada, que tu preparaste, ó SENHOR; No santuário do Senhor, que firmaram tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 18, 'O SENHOR reinará pelos séculos dos séculos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 19, 'Porque Faraó entrou cavalgando com seus carros e seus cavaleiros no mar, e o SENHOR voltou a trazer as águas do mar sobre eles; mas os filhos de Israel foram a seco por meio do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 20, 'E Miriã a profetisa, irmã de Arão, tomou um pandeiro em sua mão, e todas as mulheres saíram atrás dela com pandeiros e danças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 21, 'E Miriã lhes respondia: Cantai ao SENHOR; porque em extremo se engrandeceu, Lançando no mar ao cavalo, e ao que nele subia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 22, 'E fez Moisés que partisse Israel do mar Vermelho, e saíram ao deserto de Sur; e andaram três dias pelo deserto sem achar água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 23, 'E chegaram a Mara, e não puderam beber as águas de Mara, porque eram amargas; por isso lhe puseram o nome de Mara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 24, 'Então o povo murmurou contra Moisés, e disse: Que beberemos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 25, 'E Moisés clamou ao SENHOR; e o SENHOR lhe mostrou uma árvore, a qual quando a meteu dentro das águas, as águas se tornaram doces. Ali lhes deu estatutos e ordenanças, e ali os provou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 26, 'E disse: Se ouvires atentamente a voz do SENHOR teu Deus, e fizeres o correto diante de seus olhos, e deres ouvido a seus mandamentos, e guardares todos os seus estatutos, nenhuma enfermidade das que enviei aos egípcios te enviarei a ti; porque eu sou o SENHOR que te sara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 15, 27, 'E chegaram a Elim, onde havia doze fontes de águas, e setenta palmeiras; e assentaram ali junto às águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 1, 'Depois que partiram de Elim, toda a congregação dos filhos de Israel veio ao deserto de Sim, que está entre Elim e Sinai, aos quinze dias do segundo mês depois que saíram da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 2, 'E toda a congregação dos filhos de Israel murmurou contra Moisés e Arão no deserto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 3, 'E diziam-lhes os filhos de Israel: Bom seria se tivéssemos morrido por meio do SENHOR na terra do Egito, quando nos sentávamos junto às panelas das carnes, quando comíamos pão em fartura; pois nos tirastes a este deserto, para matar de fome a toda esta multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 4, 'E o SENHOR disse a Moisés: Eis que eu vos farei chover pão do céu; e o povo sairá, e colherá para cada um dia, para que eu lhe prove se anda em minha lei, ou não.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 5, 'Mas ao sexto dia prepararão o que coletarem, que será o dobro do que costumam colher cada dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 6, 'Então disse Moisés e Arão a todos os filhos de Israel: À tarde sabereis que o SENHOR vos tirou da terra do Egito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 7, 'E à próxima manhã vereis a glória do SENHOR; porque ele ouviu as vossas murmurações contra o SENHOR; pois quem somos nós, para que vós murmureis contra nós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 8, 'E disse Moisés: o SENHOR vos dará à tarde carne para comer, e à manhã pão em fartura; pois o SENHOR ouviu as vossas murmurações com que murmurais contra ele; pois quem somos nós? As vossas murmurações não são contra nós, mas sim contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 9, 'E disse Moisés a Arão: Dize a toda a congregação dos filhos de Israel: Aproximai-vos à presença do SENHOR; que ele ouviu vossas murmurações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 10, 'E falando Arão a toda a congregação dos filhos de Israel, olharam até o deserto, e eis a glória do SENHOR, que apareceu na nuvem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 11, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 12, 'Eu ouvi as murmurações dos filhos de Israel; fala-lhes, dizendo: Ao entardecer comereis carne, e pela manhã vos fartareis de pão, e sabereis que eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 13, 'E vinda a tarde subiram codornizes que cobriram o acampamento; e à manhã desceu orvalho em derredor do acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 14, 'E quando o orvalho cessou de descer, eis sobre a face do deserto uma coisa miúda, redonda, miúda como uma geada sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 15, 'E vendo-o os filhos de Israel, se disseram uns aos outros: Que é isto? porque não sabiam que era. Então Moisés lhes disse: É o pão que o SENHOR vos dá para comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 16, 'Isto é o que o SENHOR mandou: Colhereis dele cada um segundo puder comer; um gômer por cabeça, conforme o número de vossas pessoas, tomareis cada um para os que estão em sua tenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 17, 'E os filhos de Israel o fizeram assim: e recolheram uns mais, outros menos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 18, 'E mediam-no por gômer, e não sobrava ao que havia recolhido muito, nem faltava ao que havia recolhido pouco: cada um recolheu conforme o que havia de comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 19, 'E disse-lhes Moisés: Nenhum deixe nada disso para amanhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 20, 'Mas eles não obedeceram a Moisés, mas sim que alguns deixaram dele para outro dia, e criou bichos, e apodreceu-se; e irou-se contra eles Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 21, 'E recolhiam-no cada manhã, cada um segundo o que havia de comer: e logo que o sol aquecia, derretia-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 22, 'No sexto dia recolheram comida em dobro, dois gômeres para cada um; e todos os príncipes da congregação vieram a Moisés, e contaram-lhe isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 23, 'E ele lhes disse: Isto é o que o SENHOR disse: Amanhã é o repouso, o santo sábado do SENHOR; o que houverdes de assar, assai-o hoje, e o que houverdes de cozinhar, cozinhai-o; e tudo o que vos sobrar, guardai-o para amanhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 24, 'E eles o guardaram até a manhã, segundo que Moisés havia mandado, e não se apodreceu, nem houve nele bicho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 25, 'E disse Moisés: Comei-o hoje, porque hoje é sábado do SENHOR: hoje não achareis no campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 26, 'Nos seis dias o recolhereis; mas o sétimo dia é sábado, no qual não se achará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 27, 'E aconteceu que alguns do povo saíram no sétimo dia a recolher, e não acharam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 28, 'E o SENHOR disse a Moisés: Até quando não querereis guardar meus mandamentos e minhas leis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 29, 'Olhai que o SENHOR vos deu o sábado, e por isso vos dá no sexto dia pão para dois dias. Fique, pois, cada um em sua morada, e ninguém saia de seu lugar no sétimo dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 30, 'Assim o povo repousou o sétimo dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 31, 'E a casa de Israel o chamou maná; e era como semente de coentro, branco, e seu sabor como de bolos com mel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 32, 'E disse Moisés: Isto é o que o SENHOR mandou: Encherás um gômer dele para que se guarde para vossos descendentes, a fim de que vejam o pão que eu vos dei a comer no deserto, quando eu vos tirei da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 33, 'E disse Moisés a Arão: Toma um vaso e põe nele um gômer cheio de maná, e põe-o diante do SENHOR, para que seja guardado para vossos descendentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 34, 'E Arão o pôs diante do testemunho para guardá-lo, como o SENHOR o mandou a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 35, 'Assim os filhos de Israel comeram maná por quarenta anos, até que entraram em terra habitada; comeram maná até que chegaram ao limite da terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 16, 36, 'E um gômer é a décima parte do efa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 1, 'E toda a congregação dos filhos de Israel partiu do deserto de Sim, por suas jornadas, ao mandamento do SENHOR, e assentaram o acampamento em Refidim: e não havia água para que o povo bebesse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 2, 'E brigou o povo com Moisés, e disseram: Dá-nos água que bebamos. E Moisés lhes disse: Por que brigais comigo? Por que tentais ao SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 3, 'Assim que o povo teve ali sede de água, e murmurou contra Moisés, e disse: Por que nos fizeste subir do Egito para matar-nos de sede a nós, e a nossos filhos e a nossos gados?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 4, 'Então clamou Moisés ao SENHOR, dizendo: Que farei com este povo? Daqui um pouco me apedrejarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 5, 'E o SENHOR disse a Moisés: Passa diante do povo, e toma contigo dos anciãos de Israel; e toma também em tua mão tua vara, com que feriste o rio, e vai:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 6, 'Eis que eu estou diante de ti ali sobre a rocha em Horebe; e ferirás a rocha, e sairão dela águas, e beberá o povo. E Moisés o fez assim em presença dos anciãos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 7, 'E chamou o nome daquele lugar Massá e Meribá, pela briga dos filhos de Israel, e porque tentaram ao SENHOR, dizendo: Está, pois, o SENHOR entre nós, ou não?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 8, 'E veio Amaleque e lutou com Israel em Refidim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 9, 'E disse Moisés a Josué: Escolhe para nós homens, e sai, luta com Amaleque: amanhã eu estarei sobre o cume do morro, e a vara de Deus em minha mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 10, 'E fez Josué como lhe disse Moisés, lutando com Amaleque; e Moisés e Arão e Hur subiram ao cume do morro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 11, 'E sucedia que quando erguia Moisés sua mão, Israel prevalecia; mas quando ele baixava sua mão, prevalecia Amaleque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 12, 'E as mãos de Moisés estavam pesadas; pelo que tomaram uma pedra, e puseram-na debaixo dele, e se sentou sobre ela; e Arão e Hur sustentavam suas mãos, o um de uma parte e o outro de outra; assim houve em suas mãos firmeza até que se pôs o sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 13, 'E Josué derrotou a Amaleque e a seu povo a fio de espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 14, 'E o SENHOR disse a Moisés: Escreve isto para memória em um livro, e dize a Josué que de todo tenho de apagar a memória de Amaleque de debaixo do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 15, 'E Moisés edificou um altar, e chamou seu nome O SENHOR é minha bandeira;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 17, 16, 'E disse: Porquanto há mão sobre o trono do SENHOR, o SENHOR terá guerra com Amaleque de geração em geração.')
